// 1. Validate HMAC-SHA256 Signature
const crypto = require('crypto');
const rawBody = $input.item.binary?.data ? Buffer.from($input.item.binary.data, 'base64').toString('utf8') : JSON.stringify($input.item.json);

// Retrieve secret from environment variable or node config
const secret = $env.PROPSTACKLY_WEBHOOK_SECRET || 'your_agency_webhook_secret';
const receivedSig = $input.item.headers['x-propstackly-signature'] || $input.item.headers['x-veltrivo-signature'];

if (receivedSig) {
  const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  if (receivedSig !== expectedSig) {
    throw new Error('HMAC signature mismatch: Unauthorized request');
  }
}

// Return formatted lead parameters
const body = $input.item.json;
return [{
  json: {
    lead_id: body.lead?.id,
    agency_id: body.agency?.id,
    event_id: body.event_id,
    lead_name: body.lead?.name || 'Valued Client',
    phone: body.whatsapp_config?.recipient_phone || body.lead?.phone,
    template_name: body.whatsapp_config?.template_name || 'welcome_lead_intro',
    components: body.whatsapp_config?.components || []
  }
}];
